import 'package:firebase_core/firebase_core.dart';
import 'firebase_options.dart';

/// Platform app settings are generated by `flutterfire configure`.
class FirebaseConfig {
  // Web OAuth client from android/app/google-services.json (client_type: 3).
  static const webClientId =
      '828931163138-ga1folbkiofsvugqjdvrof6v2q85gq66.apps.googleusercontent.com';

  // iOS and macOS can be enabled after registering those apps with FlutterFire.
  static const iosClientId = '';

  static bool get isConfigured {
    try {
      options;
      return true;
    } on UnsupportedError {
      return false;
    }
  }

  static FirebaseOptions get options => DefaultFirebaseOptions.currentPlatform;
}
